import{_ as o,C as h,o as d,c as s,a2 as e,b as E,w as r,a as n,E as l,a3 as i}from"./chunks/framework.CFuv5BrO.js";const C=JSON.parse('{"title":"Hearth OS · 数据源与联网设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-数据源与联网设计说明.md","filePath":"architecture/Hearth-数据源与联网设计说明.md","lastUpdated":null}'),c={name:"architecture/Hearth-数据源与联网设计说明.md"};function p(A,t,b,B,_,g){const a=h("Mermaid");return d(),s("div",null,[t[1]||(t[1]=e('<h1 id="hearth-os-·-数据源与联网设计说明" tabindex="-1">Hearth OS · 数据源与联网设计说明 <a class="header-anchor" href="#hearth-os-·-数据源与联网设计说明" aria-label="Permalink to &quot;Hearth OS · 数据源与联网设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下来源、抽取、抓取、搜索、GitHub 相关文件，以及 <code>packages/agent-runtime/src</code> 的抓取与文档实现），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>文档抽取的格式清单、各项上限、超限截断策略</td><td><a href="./Hearth-Agent运行时设计说明.html">Hearth-Agent运行时设计说明</a></td><td>不重复，只讲来源层如何调用它</td></tr><tr><td>抓取工具恒被定义但按权限可用</td><td><a href="./Hearth-Agent运行时设计说明.html">Hearth-Agent运行时设计说明</a></td><td>不重复，本文讲抓取本身的安全规则</td></tr><tr><td>意图关键词如何影响选路</td><td><a href="./意图识别路由与执行器自动选择.html">意图识别路由与执行器自动选择</a></td><td>不展开</td></tr><tr><td>来源正文落盘与内容寻址</td><td><a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a></td><td>不展开</td></tr><tr><td>工作区如何把 URL 输入落成文件</td><td><a href="./Hearth-工作区隔离与产物设计说明.html">Hearth-工作区隔离与产物设计说明</a></td><td>不展开</td></tr><tr><td>GitHub 副作用如何被审批</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>只讲幂等与不确定处理</td></tr></tbody></table><p>本文只讲：<strong>外部资料怎么进系统、怎么去重、网页怎么安全地抓、搜索怎么接、GitHub 怎么准备与落地副作用</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>一条「按来源类型分派 → 采集并抽取 → 哈希去重 → 就绪回写知识本体」的管线，外加两条独立的联网能力（网页快照与搜索）和一条基于命令行工具的代码托管集成。服务端有两个同名文件其实只是<strong>转发门面</strong>，真实实现在共享包里。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为来源抓取逻辑写在服务端</td><td><code>web-fetch.ts</code> 与 <code>extractors.ts</code> 分别只有几行，是纯转发；实现在 <code>agent-runtime</code> 包</td></tr><tr><td>以为邮件 / 日历来源可以直接点「读取」</td><td>这两类来源的直接读取恒被拒绝，只能由外部同步流程把内容喂进来</td></tr><tr><td>以为搜索后端失败会自动换另一家</td><td>没有跨供应商降级，一家失败就直接报错</td></tr></tbody></table><hr><h2 id="_2-来源种类与生命周期" tabindex="-1">2. 来源种类与生命周期 <a class="header-anchor" href="#_2-来源种类与生命周期" aria-label="Permalink to &quot;2. 来源种类与生命周期&quot;">​</a></h2><p>来源有五类：本地文件、本地知识库、网页、邮件、日历。来源状态五种：已连接、读取中、需要用户处理、出错、已断开；条目状态三种：就绪、失败、已清除。所有来源都被标为<strong>只读</strong>。</p><p>不同来源的创建条件差别很大：</p><table tabindex="0"><thead><tr><th>来源</th><th>必备条件</th><th>默认提供者</th></tr></thead><tbody><tr><td>本地文件 / 知识库</td><td>必须给根目录，解析真实路径并校验存在与类型</td><td>本地文件 / 本地知识</td></tr><tr><td>网页</td><td>必须给至少一个允许主机；主机串会被规范化、小写、拒绝通配符与特殊字符</td><td>公共网页</td></tr><tr><td>邮件 / 日历</td><td>无需凭据即可建，但状态直接置「需要用户处理」，原因是缺凭据</td><td>未配置</td></tr></tbody></table><p>读取时先把状态置「读取中」并清空上次错误，成功后恢复「已连接」并刷新读取时间与条目数；失败时按错误类型决定是置「出错」还是「需要用户处理」——只有「需要人工过验证页」这类错误才会升级为需要用户处理。断开、重连、清除也是显式动作，清除会删掉该来源的正文目录并重置统计。</p><hr><h2 id="_3-采集、去重与就绪回写" tabindex="-1">3. 采集、去重与就绪回写 <a class="header-anchor" href="#_3-采集、去重与就绪回写" aria-label="Permalink to &quot;3. 采集、去重与就绪回写&quot;">​</a></h2><p>本地采集是递归的，有三道闸门：最多 2000 个文件、最多 12 层、单文件 25 MB；跳过隐藏目录与依赖目录；遇到符号链接<strong>不跟随</strong>，而是单独产出一条失败条目。路径会解析真实路径并检查是否仍在根目录内，防目录逃逸。</p><p>去重的思路值得单说：</p><ol><li>哈希算的是<strong>原始字节</strong>（本地文件的原始内容、网页的原始响应体），而不是抽取后的 Markdown；</li><li>若同哈希条目已存在且状态为就绪，本次直接跳过（增量采集）；</li><li>若命中跨来源的同哈希条目，会<strong>复用同一份正文文件</strong>并标记「重复于谁」，不重复占空间；</li><li>条目的业务键按类型不同：本地用相对路径，网页用最终地址，外部喂入由调用方给。</li></ol><p>条目就绪时会发一条事件，并调用装配时注入的回调把内容回写知识本体。这个回调被明确标注为<strong>尽力而为</strong>：写本体失败不会影响采集本身成功。本体的结构见<a href="./Hearth-知识本体与指代消解设计说明.html">Hearth-知识本体与指代消解设计说明</a>。</p><p>内容抽取（把各种格式转成 Markdown）由共享包完成，格式清单、上限与「超限记缺口」策略见<a href="./Hearth-Agent运行时设计说明.html">Hearth-Agent运行时设计说明</a>，此处不重复。</p><hr><h2 id="_4-网页快照-一层很厚的防护" tabindex="-1">4. 网页快照：一层很厚的防护 <a class="header-anchor" href="#_4-网页快照-一层很厚的防护" aria-label="Permalink to &quot;4. 网页快照：一层很厚的防护&quot;">​</a></h2><p>抓取不是简单的 HTTP GET，而是一串串行检查：</p>',27)),(d(),E(i,null,{default:r(()=>[l(a,{id:"mermaid-254",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E7%9B%AE%E6%A0%87%E5%9C%B0%E5%9D%80%5D%20--%3E%20B%7B%E5%8D%8F%E8%AE%AE%E4%B8%8E%E5%9C%B0%E5%9D%80%E5%90%88%E6%B3%95%3F%7D%0A%20%20%20%20B%20--%3E%7C%E5%90%A6%7C%20Z%5B%E6%8B%92%E7%BB%9D%5D%0A%20%20%20%20B%20--%3E%7C%E6%98%AF%7C%20C%7B%E4%B8%BB%E6%9C%BA%E5%9C%A8%E5%85%81%E8%AE%B8%E5%90%8D%E5%8D%95%3F%7D%0A%20%20%20%20C%20--%3E%7C%E5%90%A6%7C%20Z%0A%20%20%20%20C%20--%3E%7C%E6%98%AF%7C%20D%7BDNS%20%E8%A7%A3%E6%9E%90%E7%BB%93%E6%9E%9C%E5%90%AB%E7%A7%81%E7%BD%91%20%2F%20%E6%9C%AC%E6%9C%BA%20%2F%20%E5%85%83%E6%95%B0%E6%8D%AE%E5%9C%B0%E5%9D%80%3F%7D%0A%20%20%20%20D%20--%3E%7C%E6%98%AF%7C%20Z%0A%20%20%20%20D%20--%3E%7C%E5%90%A6%7C%20E%5B%E5%B8%A6%E8%B6%85%E6%97%B6%E4%B8%8E%E4%BD%93%E7%A7%AF%E4%B8%8A%E9%99%90%E5%8F%91%E8%B5%B7%E8%AF%B7%E6%B1%82%5D%0A%20%20%20%20E%20--%3E%20F%7B%E5%93%8D%E5%BA%94%E7%B1%BB%E5%9E%8B%E5%8F%AF%E6%94%B6%3F%7D%0A%20%20%20%20F%20--%3E%7C%E5%90%A6%7C%20Z%0A%20%20%20%20F%20--%3E%7C%E6%98%AF%7C%20G%7B%E6%98%AF%E9%AA%8C%E8%AF%81%E9%A1%B5%20%2F%20%E6%8C%91%E6%88%98%E9%A1%B5%3F%7D%0A%20%20%20%20G%20--%3E%7C%E6%98%AF%7C%20Z%0A%20%20%20%20G%20--%3E%7C%E5%90%A6%7C%20H%5B%E8%A7%A3%E7%A0%81%20%C2%B7%20%E5%87%80%E5%8C%96%20HTML%20%C2%B7%20%E8%BD%AC%20Markdown%5D%0A%20%20%20%20H%20--%3E%20I%5B%E5%AF%B9%E5%8E%9F%E5%A7%8B%E5%93%8D%E5%BA%94%E4%BD%93%E7%AE%97%E5%93%88%E5%B8%8C%E5%90%8E%E8%BF%94%E5%9B%9E%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<p>关键参数：最多手动跟随 5 次重定向、默认 20 秒超时、5 MB 体积上限（响应头预检 + 流式读取双保险）、固定 User-Agent。只接受 HTML、XHTML、纯文本三类响应；地址里带用户名密码直接拒；私网地址判定覆盖 IPv4 与 IPv6 的保留段、链路本地、回环、文档网段，并会解析 DNS 的全部结果逐个检查。</p><p>返回的是一份快照：请求地址与最终地址、时间、状态码、标题、Markdown 正文、字节数、以及<strong>对原始响应体</strong>算的哈希。HTML 净化会删脚本、样式、导航、页脚、表单等，把相对链接绝对化，优先从正文容器取内容，再转成 Markdown（与 Agent 运行时文档里讲的是同一套能力，这里补充它在来源层的调用规则）。</p><p>错误码分得极细：地址非法、协议不支持、地址带凭据、主机不允许、私网主机、私网地址、DNS 错误、重定向过多、响应类型不支持、内容为空、需要过挑战页、体积过大等。来源层据此区分「致命」与「可重试」，工作区层也据此决定是否写失败说明（见工作区文档）。</p><p>一个隐蔽的限制：虽然抓取函数支持通配主机与「允许私网」开关，但通过接口配置的网页来源<strong>无法启用通配</strong>，主机规范化又禁止通配字符，因此默认永远禁内网与本机。</p><hr><h2 id="_5-搜索-双后端-无降级" tabindex="-1">5. 搜索：双后端，无降级 <a class="header-anchor" href="#_5-搜索-双后端-无降级" aria-label="Permalink to &quot;5. 搜索：双后端，无降级&quot;">​</a></h2><p>支持 Tavily 与自建 SearXNG 两种后端，配置存在应用设置里，默认关闭。密钥用加密箱保存，界面只返回「是否已有密钥」与掩码后的值；掩码规则是短密钥全掩、长密钥保留前 2 后 4。</p><table tabindex="0"><thead><tr><th>项</th><th>规则</th></tr></thead><tbody><tr><td>查询长度</td><td>1–500 字符</td></tr><tr><td>结果数</td><td>默认 5，最多 10</td></tr><tr><td>超时</td><td>20 秒，且禁止自动跟随重定向</td></tr><tr><td>结果规范化</td><td>按地址去重、只留 http/https、去 HTML 标签、标题截 200、摘要截 500</td></tr></tbody></table><p>搜索被包装成一个 Agent 工具，但它有一道额外门槛：<strong>权限里的网络主机必须包含通配符</strong>才允许调用公共网络搜索。工具描述里会提示模型「搜到后可用抓取工具细读」。失败即抛错，不自动切到另一家供应商；唯一的「回退」是配置解析失败时回到「禁用」默认态。</p><hr><h2 id="_6-github-用命令行工具完成全部集成" tabindex="-1">6. GitHub：用命令行工具完成全部集成 <a class="header-anchor" href="#_6-github-用命令行工具完成全部集成" aria-label="Permalink to &quot;6. GitHub：用命令行工具完成全部集成&quot;">​</a></h2><p>所有操作都通过执行 <code>git</code> 与 <code>gh</code> 命令完成，不调用 REST SDK；凭据靠 Git 的凭据助手复用 gh 的登录态。默认命令超时 5 分钟，网络类命令有最多 3 次、间隔递增的重试。</p><p><strong>准备仓库</strong>：优先用本地缓存做浅克隆，没有缓存则从远端浅克隆（深度 50，超时 10 分钟）；随后补齐提交身份、校验远端存在、读取默认分支。议题类任务会开一个以任务编号命名的分支（禁止用主分支名）；PR 类任务则抓取对应 ref 并以分离头指针检出，同时校验提交哈希一致性。仓库检查给出是否干净、当前分支、HEAD、提交数、差异统计。</p><p><strong>PR 预览校验</strong>：标题与正文必填且有长度上限；有关联议题时正文必须引用它；分支与基准必须与仓库上下文严格一致；评论正文从评审稿中按成对标记提取。</p><p><strong>三类副作用的幂等设计</strong>（审批流程本身见判定审批文档）：</p><table tabindex="0"><thead><tr><th>动作</th><th>幂等手段</th><th>结果不确定时</th></tr></thead><tbody><tr><td>推送分支</td><td>推送失败后比对远端分支提交与期望提交</td><td>抛「效果不确定」交对账</td></tr><tr><td>创建 PR</td><td>先查是否已存在开放 PR；创建异常后再查一次</td><td>同上</td></tr><tr><td>发评论</td><td>先校验 PR 的 HEAD 与状态，再用带幂等键的 HTML 注释标记查重</td><td>同上</td></tr></tbody></table><p>「效果不确定」不是失败重试，而是进入人工对账队列——因为外部动作可能已经发生了，盲目重试会造成重复。对账机制见<a href="./判定审批机制说明.html">判定审批机制说明</a>。</p><hr><h2 id="_7-只读代码才会发现的事实" tabindex="-1">7. 只读代码才会发现的事实 <a class="header-anchor" href="#_7-只读代码才会发现的事实" aria-label="Permalink to &quot;7. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>服务端 <code>web-fetch.ts</code> / <code>extractors.ts</code> 是几行的转发文件，实现在共享包；共享包的入口也是纯导出。</li><li>去重哈希基于原始字节，落盘的却是抽取后的 Markdown；跨来源同内容会共享正文文件并标记重复来源。</li><li>邮件 / 日历来源不能直接读，只能由外部同步喂入；日历来源的实际喂入方在代码中未见闭环。</li><li>搜索没有跨后端自动降级，且搜索工具额外要求通配网络权限。</li><li>经接口配置的网页来源无法启用通配主机，默认永远禁止内网与本机。</li><li>GitHub 副作用失败一律转「效果不确定」对账，而不是自动重试。</li></ol><hr><h2 id="_8-与其它模块的分界" tabindex="-1">8. 与其它模块的分界 <a class="header-anchor" href="#_8-与其它模块的分界" aria-label="Permalink to &quot;8. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>服务门面与存储、加密箱、共享契约枚举、任务网络权限、git/gh 可执行与登录态</td></tr><tr><td>输出</td><td>来源与条目记录、就绪回写本体、网页快照、两个联网工具、搜索结果、GitHub 工作区与副作用回执</td></tr><tr><td>不讲</td><td>格式解析上限（Agent 运行时）、URL 输入落地（工作区）、正文落盘（存储）、审批与对账（判定审批）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>来源注册、状态机、采集与去重、外部喂入</td><td><code>apps/server/src/sources.ts</code></td></tr><tr><td>转发门面</td><td><code>apps/server/src/extractors.ts</code>、<code>web-fetch.ts</code></td></tr><tr><td>搜索服务与工具</td><td><code>apps/server/src/web-search.ts</code></td></tr><tr><td>GitHub 准备、视图、PR 预览与副作用</td><td><code>apps/server/src/github.ts</code></td></tr><tr><td>意图关键词常量</td><td><code>apps/server/src/task-intent.ts</code></td></tr><tr><td>网页抓取净化、文档抽取的真实实现</td><td><code>packages/agent-runtime/src/web-fetch.ts</code>、<code>documents.ts</code></td></tr><tr><td>抓取工具的权限接入</td><td><code>packages/agent-runtime/src/tools.ts</code></td></tr></tbody></table>',26))])}const m=o(c,[["render",p]]);export{C as __pageData,m as default};
